const updateDeal = `-- name: UpdateDeal :one
UPDATE deal d
SET name       = COALESCE($1, d.name),
    value      = COALESCE($2::numeric, d.value),
    currency   = COALESCE($3, d.currency),
    -- NULLIF because COALESCE reads NULL as "leave it alone", and clearing the close date
    -- is the one case where a client means "no date".
    close_date = CASE
                   WHEN $4::date IS NULL THEN d.close_date
                   ELSE NULLIF($4, 'null'::text)::date
               END,
    person_id  = CASE
                   WHEN $5::uuid IS NULL THEN d.person_id
                   ELSE NULLIF($5,
                               '00000000-0000-0000-0000-000000000000'::uuid)
               END,
    company_id = CASE
                   WHEN $6::uuid IS NULL THEN d.company_id
                   ELSE NULLIF($6,
                               '00000000-0000-0000-0000-000000000000'::uuid)
               END,
    owner_id   = CASE
                   WHEN $7::uuid IS NULL THEN d.owner_id
                   ELSE NULLIF($7,
                               '00000000-0000-0000-0000-000000000000'::uuid)
               END,
    lost_reason = CASE
                   WHEN $8::text IS NULL THEN d.lost_reason
                   ELSE NULLIF($8, '')
                 END,
    stage_id    = COALESCE($9, d.stage_id),
    pipeline_id = COALESCE($10, d.pipeline_id),
    -- Rule 1. Run on every update rather than only when stage_id is sent, deliberately:
    -- a stage's probability can be retuned after deals are already sitting in it, and the
    -- forecast should follow the retune instead of keeping the old numbers.
    probability = (SELECT s.probability FROM stage s
                   WHERE s.workspace_id = d.workspace_id
                     AND s.id = COALESCE($9, d.stage_id)),
    -- Rule 2.
    closed_at   = CASE
                   WHEN (SELECT s.is_won OR s.is_lost FROM stage s
                          WHERE s.workspace_id = d.workspace_id
                            AND s.id = COALESCE($9, d.stage_id))
                   THEN COALESCE(d.closed_at, now())
                   ELSE NULL
                 END,
    data        = d.data || $11,
    updated_at  = now()
WHERE d.workspace_id = $12
  AND d.id = $13
  AND d.deleted_at IS NULL
RETURNING id, name, value::float8 AS value, currency, probability, close_date,
          lost_reason, closed_at, data, created_at, updated_at,
          person_id, company_id, owner_id, pipeline_id, stage_id
`

